import hashlib,json,pathlib,shutil,sys
receipt_path,source,output=map(pathlib.Path,sys.argv[1:])
receipt=json.loads(receipt_path.read_text())
if receipt['status']!='completed':raise ValueError('Baseline receipt is not completed')
names=('native-song.wav','native-song.frames.json','native-song.writes.json','conversion.json','verification.json')
output.mkdir()
reports=[]
for name in names:
    path=source/name
    matches=[item for item in receipt['artifacts'] if item['stageId']=='candidate' and item['relativePath']=='song/'+name]
    if len(matches)!=1 or hashlib.sha256(path.read_bytes()).hexdigest()!=matches[0]['sha256']:raise ValueError('Baseline evidence no longer matches its successful receipt: '+name)
    shutil.copyfile(path,output/name)
    if hashlib.sha256((output/name).read_bytes()).hexdigest()!=matches[0]['sha256']:raise ValueError('Copied baseline evidence differs: '+name)
    reports.append(dict(filename=name,sourcePath=str(path),sha256=matches[0]['sha256']))
if reports[0]['sha256']!='251d6d80037cff63885efdf01ad312785efa1ded3c3a2708e0afc98b7511f09e':raise ValueError('Baseline must be the exact selected full WAV')
(output/'reference-reuse.json').write_text(json.dumps(dict(schemaVersion=1,receiptPath=str(receipt_path),receiptSha256=hashlib.sha256(receipt_path.read_bytes()).hexdigest(),files=reports,scope='Reuse and fingerprint-check prior completed full CPU/PCM evidence; no fresh baseline execution or rendering is claimed.'),indent=2)+chr(10))
